from collections import deque

def oranges_rotting(grid):
    m, n = len(grid), len(grid[0])
    INF = float('inf')
    best = [[INF] * n for _ in range(m)]   # earliest minute each cell rots
    for sr in range(m):
        for sc in range(n):
            if grid[sr][sc] != 2:
                continue
            dist = {(sr, sc): 0}
            queue = deque([(sr, sc)])  # a separate BFS from this rotten orange
            while queue:
                r, c = queue.popleft()
                best[r][c] = min(best[r][c], dist[(r, c)])
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1 and (nr, nc) not in dist:
                        dist[(nr, nc)] = dist[(r, c)] + 1
                        queue.append((nr, nc))
    minutes = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                if best[r][c] == INF:
                    return -1          # no rotten orange can reach it
                minutes = max(minutes, best[r][c])
    return minutes

