from collections import deque

def snakes_and_ladders(board):
    n = len(board)

    def cell(square):                  # 1-based square → (row, col)
        r, c = divmod(square - 1, n)
        return n - 1 - r, (c if r % 2 == 0 else n - 1 - c)

    moves = {1: 0}
    queue = deque([1])
    while queue:
        square = queue.popleft()
        if square == n * n:
            return moves[square]
        for nxt in range(square + 1, min(square + 6, n * n) + 1):
            r, c = cell(nxt)
            if board[r][c] != -1:
                nxt = board[r][c]      # take the snake or ladder
            if nxt not in moves:
                moves[nxt] = moves[square] + 1
                queue.append(nxt)
    return -1

