from collections import deque

def walls_and_gates(rooms):
    if not rooms:
        return
    m, n = len(rooms), len(rooms[0])
    gates = [(r, c) for r in range(m) for c in range(n) if rooms[r][c] == 0]
    for gr, gc in gates:               # one BFS per gate, keeping the minimum
        queue, dist = deque([(gr, gc)]), {(gr, gc): 0}
        while queue:
            r, c = queue.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if (0 <= nr < m and 0 <= nc < n and rooms[nr][nc] > 0
                        and (nr, nc) not in dist):
                    dist[(nr, nc)] = dist[(r, c)] + 1
                    rooms[nr][nc] = min(rooms[nr][nc], dist[(nr, nc)])
                    queue.append((nr, nc))

