def ladder_length(begin_word, end_word, word_list):
    words = set(word_list)
    if end_word not in words:
        return 0
    words -= {begin_word, end_word}
    front, back, steps = {begin_word}, {end_word}, 1
    while front and back:
        if len(front) > len(back):
            front, back = back, front  # always grow the smaller frontier
        nxt = set()
        for word in front:
            for i in range(len(word)):
                for ch in 'abcdefghijklmnopqrstuvwxyz':
                    cand = word[:i] + ch + word[i + 1:]
                    if cand in back:
                        return steps + 1   # the two searches meet
                    if cand in words:
                        words.remove(cand)
                        nxt.add(cand)
        front, steps = nxt, steps + 1
    return 0

