from collections import deque

def ladder_length(begin_word, end_word, word_list):
    words = list(set(word_list) | {begin_word})
    graph = {w: [] for w in words}
    for i, a in enumerate(words):      # compare every pair: O(N²·L)
        for b in words[i + 1:]:
            if sum(x != y for x, y in zip(a, b)) == 1:
                graph[a].append(b)
                graph[b].append(a)
    if end_word not in word_list:
        return 0
    seen, queue = {begin_word}, deque([(begin_word, 1)])
    while queue:
        word, steps = queue.popleft()
        if word == end_word:
            return steps
        for nxt in graph[word]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, steps + 1))
    return 0
